    let clash=false; for(const v of Object.values(L)){ /* v.t 는 평균 뺀 값 */ let s=0,qa=0,am=0; for(let i=0;i<avg.length;i++) am+=avg[i]; am/=avg.length; for(let i=0;i<avg.length;i++){ const a=avg[i]-am; s+=a*v.t[i]; qa+=a*a; } if(qa>0&&v.n>0&&s/(Math.sqrt(qa)*v.n)>=.9){ clash=true; break; } } if(clash) continue;
